/**
 * The hand-written list of everything the built site must carry. Every row here was
 * written because a specific requirement exists, not generated by scanning the site
 * for patterns \u2014 a scanner finds only what already matches a pattern, which is
 * exactly the failure mode this list exists to avoid: it must name a feature even
 * when the site currently has none of it, so removing the feature turns the row red
 * instead of the row quietly having nothing left to check.
 *
 * Each entry's `check` receives the built site's raw source as plain text
 * (`ctx.html`, `ctx.js`, `ctx.css`) plus a couple of parsed conveniences, and returns
 * true when that one requirement is satisfied. tools/check-site-contract.mjs is the
 * only thing that actually reads files from disk; this module stays pure so tests
 * can hand it small in-memory fixtures.
 */

/**
 * @typedef {object} ContractContext
 * @property {string} html    site/index.html
 * @property {string} js      every site/scripts/**\/*.{js,mjs} file, concatenated
 * @property {string} css     every site/styles/**\/*.css file, concatenated
 * @property {string[]} rootFiles     filenames present at the repository root
 * @property {unknown} featuresData   parsed site/data/features.json, or null
 */

/**
 * @typedef {object} ContractItem
 * @property {string} id
 * @property {string} description
 * @property {(ctx: ContractContext) => boolean} check
 */

const FORBIDDEN_HOST_SNIPPETS = [
  'googleapis.com',
  'gstatic.com',
  'google-analytics.com',
  'googletagmanager.com',
  'gtag(',
  'jsdelivr.net',
  'unpkg.com',
  'cdnjs.cloudflare.com',
  'plausible.io',
  'segment.com',
  'segment.io',
  'doubleclick.net',
  'facebook.net/tr',
];

/** @type {ContractItem[]} */
export const CONTRACT = [
  {
    id: 'installer-button-present',
    description: 'The Download panel renders a real installer download control (#download-button).',
    check: (ctx) => /downloadLink\.id\s*=\s*['"]download-button['"]/.test(ctx.js),
  },
  {
    id: 'installer-absent-until-published',
    description: 'The download button starts hidden and only unhides when a release is actually published.',
    check: (ctx) => /downloadLink\.hidden\s*=\s*!release\.published/.test(ctx.js),
  },
  {
    id: 'installer-honest-empty-state',
    description: 'An honest "no release published yet" state exists and is shown by default.',
    check: (ctx) => /data-contract['"]?\]?\s*=\s*['"]install-empty-state['"]|dataset\.contract\s*=\s*['"]install-empty-state['"]/.test(ctx.js),
  },
  {
    id: 'installer-no-guessed-url',
    description: 'The inline release data defaults to "published": false, never a guessed asset URL.',
    check: (ctx) => /"published"\s*:\s*false/.test(ctx.html),
  },
  {
    id: 'tabs-dockable',
    description: 'The tab strip can be docked (top or side) and the shell records the current dock position.',
    check: (ctx) => /setDock/.test(ctx.js) && /tabDock/.test(ctx.js) && /data-tab-dock/.test(ctx.css),
  },
  {
    id: 'tabs-overflow-never-silent',
    description: 'Tabs that stop fitting the strip remain reachable through an always-available overflow menu.',
    check: (ctx) => /computeVisible/.test(ctx.js) && /tab-overflow-menu/.test(ctx.js) && /tab-overflow-menu/.test(ctx.css),
  },
  {
    id: 'tabs-reorder',
    description: 'Tabs can be reordered, both by dragging and through an accessible move-earlier/move-later control.',
    check: (ctx) => /draggable/.test(ctx.js) && /move\(id/.test(ctx.js),
  },
  {
    id: 'tabs-pin',
    description: 'Tabs can be pinned and unpinned, and a pinned tab is never sent to overflow.',
    check: (ctx) => /togglePin/.test(ctx.js) && /pinnedSet\.has/.test(ctx.js),
  },
  {
    id: 'tabs-group',
    description: 'Tabs can be assigned to a named group, rendered with a group label.',
    check: (ctx) => /setGroup/.test(ctx.js) && /tab-group__label/.test(ctx.css),
  },
  {
    id: 'tabs-persist-across-reload',
    description: 'Tab order, pins, groups, active tab and dock position persist to localStorage and reload from it.',
    check: (ctx) => /tds-site:tabs:v1/.test(ctx.js) && /localStorage\.setItem/.test(ctx.js) && /localStorage\.getItem/.test(ctx.js),
  },
  {
    id: 'settings-theme',
    description: 'Settings offers light, dark and system theme, applied as a data-theme attribute.',
    check: (ctx) => /dataset\.theme/.test(ctx.js) && /settings\.theme\.system/.test(ctx.js),
  },
  {
    id: 'settings-density',
    description: 'Settings offers three density levels (comfortable, compact, spacious).',
    check: (ctx) =>
      ['comfortable', 'compact', 'spacious'].every((d) => new RegExp(`data-density="${d}"|density:\\s*['"]${d}`).test(ctx.css + ctx.js)),
  },
  {
    id: 'settings-accent-full-spectrum',
    description: 'The accent colour picker is three HSL sliders across the full range, not a fixed row of swatches.',
    check: (ctx) =>
      /'accent-hue'/.test(ctx.js) &&
      /'accent-sat'/.test(ctx.js) &&
      /'accent-light'/.test(ctx.js) &&
      /'accent-hue',\s*'settings\.accent\.hue',\s*0,\s*360/.test(ctx.js),
  },
  {
    id: 'settings-font-cjk-safe',
    description: 'A font choice exists with an explicit CJK-safe fallback chain, not a Latin-only stack.',
    check: (ctx) => /--font-cjk/.test(ctx.css) && /Noto Sans HK/.test(ctx.css),
  },
  {
    id: 'settings-persist',
    description: 'Appearance and language preferences persist to localStorage across reloads.',
    check: (ctx) => /tds-site:prefs:v1/.test(ctx.js),
  },
  {
    id: 'search-present-on-every-panel',
    description: 'Every one of the six tab panels mounts its own search bar instance.',
    check: (ctx) => {
      const ids = ['overview', 'features', 'download', 'docs', 'settings', 'about'];
      // overview intentionally has no standalone search bar of its own content
      // (it is a short, single-screen introduction); every other panel mounts one.
      const withSearch = ['features-search', 'download-search', 'docs-search', 'settings-search', 'about-search'];
      return withSearch.every((mountId) => ctx.js.includes(`id = '${mountId}'`) || ctx.js.includes(`id="${mountId}"`));
    },
  },
  {
    id: 'search-has-own-regex-builder',
    description: 'Each search field has its own regex mode toggle and a live pattern-testing surface anchored beside it.',
    check: (ctx) => /regex-popover/.test(ctx.css) && /useRegex/.test(ctx.js) && /new RegExp\(pattern/.test(ctx.js),
  },
  {
    id: 'search-regex-invalid-handled',
    description: 'An invalid regular expression is caught and reported, never left to throw.',
    check: (ctx) => /catch[\s\S]{0,80}search\.regex\.invalid/.test(ctx.js),
  },
  {
    id: 'notifications-nonblocking-corner',
    description: 'Notifications render in a fixed, corner-anchored region rather than a blocking modal.',
    check: (ctx) => /\.notification-region\s*\{[\s\S]*?position:\s*fixed/.test(ctx.css) && /aria-live="polite"/.test(ctx.html),
  },
  {
    id: 'notifications-accessible-live-region',
    description: 'The notification region is announced to assistive technology via aria-live.',
    check: (ctx) => /role="status"/.test(ctx.html) && /aria-live/.test(ctx.html),
  },
  {
    id: 'three-language-modes',
    description: 'Exactly the three required language modes exist: English, Cantonese and bilingual.',
    check: (ctx) => /LANGUAGE_MODES[\s\S]{0,40}\[.*'en'.*'yue'.*'bilingual'.*\]/.test(ctx.js),
  },
  {
    id: 'bilingual-secondary-line-smaller',
    description: 'Bilingual mode renders a visibly smaller secondary line so it does not crowd the primary language.',
    check: (ctx) => /\.lang-line--secondary\s*\{[\s\S]*?font:\s*var\(--type-body-small\)/.test(ctx.css),
  },
  {
    id: 'cantonese-never-silently-empty',
    description: 'Every Cantonese key falls back to English rather than ever rendering blank.',
    check: (ctx) => /resolveSingle/.test(ctx.js) && /function resolveSingle/.test(ctx.js),
  },
  {
    id: 'responsive-min-320',
    description: 'The layout is responsive from roughly 320px wide with no forced horizontal overflow.',
    check: (ctx) => /min-width:\s*320px/.test(ctx.css) && /overflow-x:\s*hidden/.test(ctx.css),
  },
  {
    id: 'touch-target-minimum',
    description: 'Interactive elements respect a 44px minimum touch target.',
    check: (ctx) => /--target-min:\s*44px/.test(ctx.css),
  },
  {
    id: 'keyboard-focus-visible',
    description: 'Focus is visibly indicated on every interactive component, not suppressed.',
    check: (ctx) => (ctx.css.match(/:focus-visible/g) || []).length >= 5,
  },
  {
    id: 'tablist-roles-present',
    description: 'The tab strip uses real tablist/tab/tabpanel ARIA roles.',
    check: (ctx) => /role="tablist"/.test(ctx.html) && /role="tabpanel"/.test(ctx.html) && /role',\s*'tab'|setAttribute\('role', 'tab'\)/.test(ctx.js),
  },
  {
    id: 'skip-link-present',
    description: 'A skip-to-content link is the first focusable element on the page.',
    check: (ctx) => /class="skip-link"[\s\S]{0,40}href="#main-content"/.test(ctx.html) && /id="main-content"/.test(ctx.html),
  },
  {
    id: 'reduced-motion-respected',
    description: 'Motion is reduced to zero under prefers-reduced-motion.',
    check: (ctx) => /prefers-reduced-motion:\s*reduce/.test(ctx.css),
  },
  {
    id: 'og-tags-present',
    description: 'The social embed meta tags (title, description, image, dimensions, alt, card type) are hard-coded in <head>.',
    check: (ctx) =>
      [
        'property="og:title"',
        'property="og:description"',
        'property="og:image"',
        'property="og:image:width"',
        'property="og:image:height"',
        'property="og:image:alt"',
        'name="twitter:card" content="summary_large_image"',
        'name="theme-color"',
      ].every((needle) => ctx.html.includes(needle)),
  },
  {
    id: 'og-image-absolute-https',
    description: 'og:image is an absolute https:// URL, never a relative path a crawler cannot resolve.',
    check: (ctx) => {
      const match = /property="og:image"\s+content="([^"]+)"/.exec(ctx.html);
      return !!match && match[1].startsWith('https://');
    },
  },
  {
    id: 'og-image-references-social-preview-asset',
    description: 'og:image points at the committed social-preview.png asset by name.',
    check: (ctx) => /property="og:image"\s+content="[^"]*social-preview\.png"/.test(ctx.html),
  },
  {
    id: 'social-preview-file-exists',
    description: 'social-preview.png exists at the repository root as a real, product-specific image.',
    check: (ctx) => ctx.rootFiles.includes('social-preview.png'),
  },
  {
    id: 'no-content-delivery-network',
    description: 'No asset, font or script is loaded from a third-party content delivery network.',
    check: (ctx) => {
      const combined = `${ctx.html}\n${ctx.js}\n${ctx.css}`;
      return !FORBIDDEN_HOST_SNIPPETS.some((needle) => combined.includes(needle));
    },
  },
  {
    id: 'no-analytics-or-tracking',
    description: 'No analytics or third-party tracking snippet is present anywhere in the built site.',
    check: (ctx) => {
      const combined = `${ctx.html}\n${ctx.js}`;
      return !/analytics|gtag\(|fbq\(/i.test(combined);
    },
  },
  {
    id: 'docs-bundle-loaded-same-origin',
    description: 'The documentation browser loads its bundle from a local, same-origin file, never a remote one.',
    check: (ctx) => /docs-bundle\.json/.test(ctx.js) && !/https?:\/\/[^"'\s]*docs-bundle\.json/.test(ctx.js),
  },
  {
    id: 'docs-per-article-suggested-links',
    description: 'The documentation viewer renders each article\u2019s suggested-next-articles section.',
    check: (ctx) => /docs\.suggested/.test(ctx.js) && /found\.suggested/.test(ctx.js),
  },
  {
    id: 'features-tab-exhaustive-and-honest',
    description: 'The Features data file enumerates real features with an honest, non-uniform status per entry.',
    check: (ctx) => {
      if (!Array.isArray(ctx.featuresData) || ctx.featuresData.length < 10) return false;
      const statuses = new Set(ctx.featuresData.map((f) => f.status));
      const validStatuses = ['shipped', 'in-progress', 'planned'];
      const allValid = ctx.featuresData.every((f) => validStatuses.includes(f.status));
      const hasShipped = statuses.has('shipped');
      const hasUnshipped = statuses.has('planned') || statuses.has('in-progress');
      return allValid && hasShipped && hasUnshipped;
    },
  },
  {
    id: 'language-switcher-present',
    description: 'A language switcher control offering all three modes is present in the page chrome.',
    check: (ctx) => /id="language-select"/.test(ctx.html) && /value="bilingual"/.test(ctx.html),
  },
  {
    id: 'theme-color-meta-syncs-with-accent',
    description: 'The theme-color meta tag is kept in sync with the live accent colour and theme.',
    check: (ctx) => /syncThemeColor/.test(ctx.js) && /name="theme-color"/.test(ctx.html),
  },
];
